"""A small command-line parser with typed values, conflicts, and useful diagnostics."""
import math
import re
from dataclasses import dataclass, field
from datetime import datetime
from diagnostics import cli_error, finish
from help_render import render_help
from model import COMMANDS, ALIASES, COLORS, SHELLS, Option


def jaro_winkler(a, b):
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    radius = max(max(len(a), len(b)) // 2 - 1, 0)
    hits_a = [False] * len(a)
    hits_b = [False] * len(b)
    hits = 0
    for i, c in enumerate(a):
        for j in range(max(0, i-radius), min(len(b), i+radius+1)):
            if not hits_b[j] and c == b[j]:
                hits_a[i] = hits_b[j] = True
                hits += 1
                break
    if not hits:
        return 0.0
    aa = [c for c, hit in zip(a, hits_a) if hit]
    bb = [c for c, hit in zip(b, hits_b) if hit]
    transpositions = sum(x != y for x,y in zip(aa, bb)) / 2.0
    score = (hits/len(a) + hits/len(b) + (hits-transpositions)/hits) / 3.0
    if score > 0.7:
        prefix = 0
        for x, y in zip(a[:4], b[:4]):
            if x != y:
                break
            prefix += 1
        score += prefix * 0.1 * (1.0-score)
    return score


def similar(value, choices):
    ranked = [(jaro_winkler(value, candidate), index, candidate) for index,candidate in enumerate(choices)]
    return [c for score,i,c in sorted(ranked) if score > 0.7]


def valid_delay(value):
    if not value or value != value.strip():
        value = value.strip()
    if not value:
        return False
    # Bare integers are seconds. Other expressions follow a calendar/time grammar.
    if re.fullmatch(r'[+-]?\d+', value):
        return -(1 << 63) <= int(value) < (1 << 63)
    s = value.lower()
    if re.fullmatch(r'\d{1,2}\.\d{1,2}', s):
        a,b=map(int,s.split('.'))
        return 1 <= a <= 12 and 1 <= b <= 31
    keywords = r'(?:today|tomorrow|yesterday|now|noon|midnight)'
    weekday = r'(?:mon(?:day)?|tue(?:sday)?|wed(?:nesday)?|thu(?:rsday)?|fri(?:day)?|sat(?:urday)?|sun(?:day)?)'
    clock = r'(?:[0-9]{1,2}(?::[0-9]{1,2}(?::[0-9]{1,2})?)?\s*(?:am|pm)?(?:\s*(?:utc|gmt|[+-]\d\d:?\d\d))?)'
    if re.fullmatch(keywords + r'(?:\s+'+clock+r')?', s):
        return True
    if re.fullmatch(r'(?:(?:next|last|this)\s+)?'+weekday+r'(?:\s+'+clock+r')?',s):
        return True
    units = r'(?:seconds?|secs?|s|minutes?|mins?|m|hours?|hrs?|h|days?|d|weeks?|w|months?|mons?|mo|years?|yrs?|y)'
    duration = r'[+-]?\d+\s*' + units
    if re.fullmatch(r'(?:' + duration + r'\s*)+(?:(?:ago)|(?:'+clock+r'))?',s):
        return True
    if re.fullmatch(r'(?:next|last|this)\s+(?:week|month|year)',s):
        return True
    # Date with an optional clock; zero padding is not required.
    date = re.match(r'^(\d{4})-(\d{1,2})-(\d{1,2})(.*)$',s)
    if date:
        try:
            datetime(int(date[1]),int(date[2]),int(date[3]))
        except ValueError:
            return False
        tail=date[4]
        if not tail:
            return True
        if tail[0] in ('t',' '):
            tail=tail[1:]
            tail=tail[:-1] if tail.endswith('z') else tail
            return bool(re.fullmatch(clock,tail)) and clock_valid(tail)
        return False
    date = re.match(r'^(\d{1,2})/(\d{1,2})(?:/(\d{2}|\d{4}))?(.*)$',s)
    if date:
        try:
            datetime(int(date[3] or '2024'),int(date[1]),int(date[2]))
        except ValueError:
            return False
        return not date[4] or bool(re.fullmatch(r'\s+'+clock,date[4]))
    months=r'(?:january|february|march|april|may|june|july|august|september|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|oct|nov|dec)'
    if re.fullmatch(r'(?:\d{1,2}\s+'+months+r'(?:\s+\d{4})?|'+months+r'\s+\d{1,2}(?:\s+\d{4})?)\s+'+clock,s):
        return True
    return bool(re.fullmatch(clock,s)) and clock_valid(s)


def clock_valid(s):
    match=re.match(r'(\d{1,2})(?::(\d{1,2})(?::(\d{1,2}))?)?',s)
    if not match:
        return False
    h,m,sec = int(match[1]), int(match[2] or 0), int(match[3] or 0)
    return h <= (12 if 'am' in s or 'pm' in s else 23) and m < 60 and sec < 60


def missing_value(display, kind):
    text = f"a value is required for '{display}' but none was supplied"
    if kind in ('color','shell'):
        choices = COLORS if kind == 'color' else SHELLS
        text += '\n  [possible values: ' + ', '.join(choices) + ']'
    cli_error(text)


def typed_value(value, kind, display):
    problem = None
    if kind in ('path','color','shell') and value == '':
        missing_value(display,kind)
    if kind in ('uint','int32'):
        signed = kind == 'int32'
        if value == '':
            problem = 'cannot parse integer from empty string'
        elif not re.fullmatch(r'[+-]?\d+' if signed else r'\+?\d+',value, flags=re.ASCII):
            problem = 'invalid digit found in string'
        else:
            number = int(value)
            if number >= (1 << (63 if signed else 64)):
                problem = 'number too large to fit in target type'
            elif signed and number < -(1 << 63):
                problem = 'number too small to fit in target type'
            elif signed and not -(1 << 31) <= number < (1 << 31):
                problem = f'{number} is not in -2147483648..=2147483647'
        if not problem:
            return number
    elif kind == 'status':
        if value not in ('queued','Queued','running','Running','done','Done','success','Success'):
            problem = 'Matching variant not found'
    elif kind == 'signal':
        s = value.lower()
        if s.startswith('sig'):
            s = s[3:]
        if s not in ('int','kill','term','cont','stop','2','9','15','18','19'):
            problem = 'Matching variant not found'
    elif kind == 'delay':
        if not valid_delay(value):
            problem = 'could not parse as seconds or date expression'
    elif kind in ('color','shell'):
        choices = COLORS if kind == 'color' else SHELLS
        if value not in choices:
            tips = []
            suggestions = similar(value, choices)
            if suggestions:
                tips = [f"a similar value exists: '{suggestions[-1]}'"]
            cli_error(f"invalid value '{value}' for '{display}'\n  [possible values: " + ', '.join(choices) + ']', tips=tips)
    if problem:
        cli_error(f"invalid value '{value}' for '{display}': {problem}")
    return value


@dataclass
class Parsed:
    command: object
    values: dict = field(default_factory=dict)
    used: list = field(default_factory=list)
    positions: list = field(default_factory=list)
    root: object = None


class Parser:
    def __init__(self, program):
        self.program=program

    def smart_usage(self, state, extra=(), exclude=(), required=()):
        c=state.command
        used=[x for x in state.used if x not in exclude]
        for x in extra:
            if x not in used:
                used.append(x)
        req=[x for x in required if x not in used]
        used=req+used
        if not used and not required and not extra:
            return c.default_usage(self.program)
        text=[self.program]
        if c.name:
            text.append(c.name)
        for item in used:
            if item.startswith('@'):
                continue
            opt=c.find_option('--'+item)
            if opt:
                text.append(opt.display)
        for i,p in enumerate(c.positionals):
            text.append(p.display(p.required or ('@'+str(i)) in used))
        if c.child_required:
            text.append('<COMMAND>')
        return ' '.join(text)

    def unknown(self, state, token, excess=False, after_double=False, suppress_suggestions=False):
        c=state.command
        usage = c.default_usage(self.program) if excess else self.smart_usage(state)
        tips=[]
        if c.children and (not token.startswith('-') or after_double):
            canonical=ALIASES.get(token,token) if not c.name else token
            if after_double and canonical in c.children:
                tips.append(f"subcommand '{token}' exists; to use it, remove the '--' before it")
                cli_error(f"unexpected argument '{token}' found",c.default_usage(self.program),tips)
            return self.unknown_subcommand(c,token,not suppress_suggestions)
        if token.startswith('-') and not excess:
            suggestion=None
            if token.startswith('--'):
                longnames=[o.long for o in c.options]
                suggestions=similar(token[2:],longnames)
                if suggestions:
                    suggestion=suggestions[-1]
                    tips.append(f"a similar argument exists: '--{suggestion}'")
                    usage=self.smart_usage(state,extra=(suggestion,))
            if c.positionals and (not suggestion or any(p.required for p in c.positionals)):
                tips.append(f"to pass '{token}' as a value, use '-- {token}'")
        cli_error(f"unexpected argument '{token}' found",usage,tips)

    def unknown_subcommand(self, c, token, suggestions=True):
        tips=[]
        if suggestions:
            candidates=[]
            for name in c.children:
                candidates.append(name)
                if not c.name:
                    candidates += [a for a,v in ALIASES.items() if v==name]
            matches=similar(token,candidates)
            if len(matches)==1:
                tips.append(f"a similar subcommand exists: '{matches[0]}'")
            elif matches:
                tips.append('some similar subcommands exist: '+', '.join("'"+m+"'" for m in matches))
        cli_error(f"unrecognized subcommand '{token}'",c.default_usage(self.program),tips)

    def show_help(self,c,long=True):
        finish(out=render_help(c.name,long,self.program))

    def help_path(self,c,args):
        current=c
        path=c.name
        for token in args:
            canonical=ALIASES.get(token,token) if not current.name else token
            if canonical not in current.children:
                self.unknown_subcommand(current,token,False)
            if canonical=='help':
                path=(current.name+' help').strip()
                # The help-of-help command has no further descendants.
                from model import Command
                current=Command(path,positionals=[])
            else:
                path=(current.name+' '+canonical).strip()
                current=COMMANDS[path]
        finish(out=render_help(current.name,True,self.program))

    def parse(self,args):
        state=self.parse_command(COMMANDS[''],args,None)
        if state.root is None:
            state.root=state
        return state

    def parse_command(self,c,args,root_state):
        st=Parsed(c,positions=[[] for p in c.positionals],root=root_state)
        i=0
        position=0
        end_options=False
        trailing=False
        while i < len(args):
            word=args[i]
            if word=='--' and not end_options and not trailing:
                end_options=True
                i+=1
                continue
            is_option=word.startswith('-') and word!='-' and not end_options and not trailing
            if is_option:
                if word.startswith('--'):
                    spelling,sep,attached=word.partition('=')
                    opt=c.find_option(spelling)
                    if opt is None:
                        self.unknown(st,spelling)
                    options=[(opt,attached if sep else None,spelling)]
                else:
                    options=[]
                    remaining=word[1:]
                    # Short clusters are processed in order so invalid suffixes
                    # preserve the previously supplied switches in the usage.
                    while remaining:
                        spelling='-'+remaining[0]
                        opt=c.find_option(spelling)
                        if opt is None:
                            self.unknown(st,spelling)
                        remaining=remaining[1:]
                        attached=None
                        if opt.value:
                            if remaining:
                                attached=remaining[1:] if remaining.startswith('=') else remaining
                                remaining=''
                        elif remaining.startswith('='):
                            attached=remaining[1:]
                            remaining=''
                        if remaining:
                            self.add_flag(st,opt,attached,spelling)
                        else:
                            options=[(opt,attached,spelling)]
                for opt,attached,spelling in options:
                    if not opt.value:
                        self.add_flag(st,opt,attached,spelling)
                        continue
                    if opt.action=='set' and opt.long in st.values:
                        cli_error(f"the argument '{opt.display}' cannot be used multiple times",c.default_usage(self.program))
                    vals=[]
                    if attached is not None:
                        vals.append(typed_value(attached,opt.kind,opt.display))
                    if attached is None or opt.many:
                        while i+1 < len(args):
                            nxt=args[i+1]
                            if nxt.startswith('-') and nxt!='-':
                                break
                            i+=1
                            vals.append(typed_value(nxt,opt.kind,opt.display))
                            if not opt.many:
                                break
                    if not vals:
                        if i+1 < len(args):
                            nxt=args[i+1]
                            key=nxt.split('=',1)[0] if nxt.startswith('--') else nxt[:2]
                            if nxt != '--' and not c.find_option(key):
                                self.unknown(st,key)
                        missing_value(opt.display,opt.kind)
                    if opt.long not in st.used:
                        st.used.append(opt.long)
                    if opt.action=='append':
                        st.values.setdefault(opt.long,[]).extend(vals)
                    else:
                        st.values[opt.long]=vals[0] if not opt.many else vals
                i+=1
                continue
            if c.children:
                canonical=ALIASES.get(word,word) if not c.name else word
                if end_options:
                    self.unknown(st,word,after_double=True)
                if canonical not in c.children:
                    self.unknown_subcommand(c,word)
                if canonical=='help':
                    self.help_path(c,args[i+1:])
                child=COMMANDS[(c.name+' '+canonical).strip()]
                self.validate(st)
                return self.parse_command(child,args[i+1:],root_state or st)
            if position>=len(c.positionals):
                self.unknown(st,word,excess=True)
            p=c.positionals[position]
            val=typed_value(word,p.kind,p.display(True))
            st.positions[position].append(val)
            marker='@'+str(position)
            if marker not in st.used:
                st.used.append(marker)
            if not p.many:
                position+=1
            if c.trailing:
                trailing=True
            i+=1
        if c.child_required and not args:
            finish(err=render_help(c.name,False,self.program)+'\n',status=2)
        self.validate(st)
        return st

    def add_flag(self,st,opt,attached,spelling):
        c=st.command
        if attached is not None:
            cli_error(f"unexpected value '{attached}' for '{opt.display}' found; no more were expected",
                      self.smart_usage(st,extra=(opt.long,)))
        if opt.long=='help':
            self.show_help(c,spelling=='--help')
        if opt.long=='version':
            finish(out='pueue 4.0.4\n')
        if opt.action!='count' and opt.long in st.values:
            cli_error(f"the argument '{opt.display}' cannot be used multiple times",c.default_usage(self.program))
        if opt.long not in st.used:
            st.used.append(opt.long)
        st.values[opt.long] = min(255,st.values.get(opt.long,0)+1) if opt.action=='count' else True

    def validate(self,st):
        c=st.command
        for name in st.used:
            opt=c.find_option('--'+name)
            if not opt:
                continue
            conflicts=[x for x in st.used if x in opt.conflicts]
            if conflicts:
                desc=[c.find_option('--'+x).display for x in conflicts]
                if len(desc)==1:
                    msg=f"the argument '{opt.display}' cannot be used with '{desc[0]}'"
                else:
                    msg=f"the argument '{opt.display}' cannot be used with:\n"+'\n'.join('  '+d for d in desc)
                cli_error(msg,self.smart_usage(st,exclude=conflicts))
        required=[]
        missing=[]
        if c.name=='add' and st.values.get('follow') and not any(st.values.get(x) for x in ('immediate','stashed','delay')):
            required.append('immediate')
            missing.append('--immediate')
        for i,p in enumerate(c.positionals):
            if p.required and not st.positions[i]:
                missing.append(p.display(True))
        if c.child_required:
            # Validated separately on entering a subcommand, which supplies COMMAND.
            pass
        if missing:
            text='the following required arguments were not provided:\n'+'\n'.join('  '+m for m in missing)
            # Required-argument errors omit the catch-all [OPTIONS] marker.
            if not st.used and not required:
