"""Output and diagnostic formatting for the command-line application."""
import os
import sys

class Finished(Exception):
    def __init__(self, status=0, out='', err=''):
        super().__init__(status)
        self.status, self.out, self.err = status, out, err


def finish(out='', err='', status=0):
    raise Finished(status, out, err)


def cli_error(message, usage=None, tips=(), suffix=None):
    text = 'error: ' + message + '\n'
    if tips:
        text += '\n' + ''.join('  tip: ' + tip + '\n' for tip in tips)
    if usage:
        text += '\nUsage: ' + usage + '\n'
    text += "\nFor more information, try '--help'.\n" if suffix is None else suffix
    finish(err=text, status=2)


def runtime_error(messages, line=61, path='pueue/src/bin/pueue.rs'):
    if isinstance(messages, str):
        messages = [messages]
    text = 'Error: \n'
    for n, message in enumerate(messages):
        text += f'   {n}: \x1b[91m' + message.replace('\n', '\n      ') + '\x1b[0m\n'
    text += f'\nLocation:\n   \x1b[35m{path}\x1b[0m:\x1b[35m{line}\x1b[0m\n\n'
    text += ('Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.\n'
             'Run with RUST_BACKTRACE=full to include source snippets.\n')
    finish(err=text, status=1)


def os_error(error):
    return f'{error.strerror or os.strerror(error.errno)} (os error {error.errno})'


def debug_quote(text):
    # Rust's Debug representation for filesystem paths and configuration strings.
    replacements = {'\\':'\\\\','"':'\\"','\n':'\\n','\r':'\\r','\t':'\\t','\0':'\\0'}
    out = ''
    for c in str(text):
        if c in replacements:
            out += replacements[c]
        elif ord(c) < 32 or ord(c) == 127:
            out += '\\u{' + format(ord(c),'x') + '}'
        else:
            out += c
    return '"' + out + '"'
