    months=r'(?:january|february|march|april|may|june|july|august|september|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|oct|nov|dec)'
    if re.fullmatch(r'(?:\d{1,2}\s+'+months+r'(?:\s+\d{4})?|'+months+r'\s+\d{1,2}(?:\s+\d{4})?)\s+'+clock,s):
        return True
    return bool(re.fullmatch(clock,s)) and clock_valid(s)


def clock_valid(s):
    match=re.match(r'(\d{1,2})(?::(\d{1,2})(?::(\d{1,2}))?)?',s)
    if not match:
        return False
    h,m,sec = int(match[1]), int(match[2] or 0), int(match[3] or 0)
    return h <= (12 if 'am' in s or 'pm' in s else 23) and m < 60 and sec < 60


def missing_value(display, kind):
    text = f"a value is required for '{display}' but none was supplied"
    if kind in ('color','shell'):
        choices = COLORS if kind == 'color' else SHELLS
        text += '\n  [possible values: ' + ', '.join(choices) + ']'
    cli_error(text)


def typed_value(value, kind, display):
    problem = None
    if kind in ('path','color','shell') and value == '':
        missing_value(display,kind)
    if kind in ('uint','int32'):
        signed = kind == 'int32'
        if value == '':
            problem = 'cannot parse integer from empty string'
        elif not re.fullmatch(r'[+-]?\d+' if signed else r'\+?\d+',value, flags=re.ASCII):
            problem = 'invalid digit found in string'
        else:
            number = int(value)
            if number >= (1 << (63 if signed else 64)):
                problem = 'number too large to fit in target type'
            elif signed and number < -(1 << 63):
                problem = 'number too small to fit in target type'
            elif signed and not -(1 << 31) <= number < (1 << 31):
                problem = f'{number} is not in -2147483648..=2147483647'
        if not problem:
            return number
    elif kind == 'status':
        if value not in ('queued','Queued','running','Running','done','Done','success','Success'):
            problem = 'Matching variant not found'
    elif kind == 'signal':
        s = value.lower()
        if s.startswith('sig'):
            s = s[3:]
        if s not in ('int','kill','term','cont','stop','2','9','15','18','19'):
            problem = 'Matching variant not found'
    elif kind == 'delay':
        if not valid_delay(value):
            problem = 'could not parse as seconds or date expression'
    elif kind in ('color','shell'):
        choices = COLORS if kind == 'color' else SHELLS
        if value not in choices:
            tips = []
            suggestions = similar(value, choices)
            if suggestions:
                tips = [f"a similar value exists: '{suggestions[-1]}'"]
            cli_error(f"invalid value '{value}' for '{display}'\n  [possible values: " + ', '.join(choices) + ']', tips=tips)
    if problem:
        cli_error(f"invalid value '{value}' for '{display}': {problem}")
    return value


@dataclass
class Parsed:
    command: object
    values: dict = field(default_factory=dict)
    used: list = field(default_factory=list)
    positions: list = field(default_factory=list)
    root: object = None


class Parser:
    def __init__(self, program):
        self.program=program

    def smart_usage(self, state, extra=(), exclude=(), required=()):
        c=state.command
        used=[x for x in state.used if x not in exclude]
        for x in extra:
            if x not in used:
                used.append(x)
        req=[x for x in required if x not in used]
        used=req+used
        if not used and not required and not extra:
            return c.default_usage(self.program)
        text=[self.program]
        if c.name:
            text.append(c.name)
        for item in used:
            if item.startswith('@'):
                continue
            opt=c.find_option('--'+item)
            if opt:
                text.append(opt.display)
        for i,p in enumerate(c.positionals):
            text.append(p.display(p.required or ('@'+str(i)) in used))
        if c.child_required:
            text.append('<COMMAND>')
