"""Generate shell completion programs from the command definitions.

Each backend emits its shell's native completion interface. No external client,
completion executable, or daemon is needed to generate these files.
"""
from dataclasses import dataclass, field
import re
from model import COMMANDS, COLORS, SHELLS
from help_text import HELP_TEXT

HELP_DESCRIPTION = 'Print this message or the help of the given subcommand(s)'


def compact_docs(name):
    text=HELP_TEXT[name]['short']
    about=text.split('\n\nUsage:')[0].replace('\n',' ')
    opts={}; positions={}; section=''; key=None
    for line in text.splitlines():
        if line in ('Arguments:','Options:','Commands:'):
            section=line;key=None
            continue
        if not line:
            key=None
            continue
        if section=='Options:':
            m=re.match(r'^ {2,6}(-\S.*?)( {2,})(.*)$',line)
            if m:
                key=re.search(r'--([\w-]+)',m[1])[1]
                opts[key]=m[3]
            elif key and line.startswith(' '):
                opts[key]+=' '+line.strip()
        elif section=='Arguments:':
            m=re.match(r'^  [<\[]([A-Z_]+)[>\]](?:\.\.\.)?  (.*)$',line)
            if m:
                key=m[1];positions[key]=m[2]
            elif key and line.startswith(' '):
                positions[key]+=' '+line.strip()
    for d in (opts,positions):
        for k in d:
            d[k]=re.sub(r' \[(?:default|possible values):[^\]]*\]','',d[k])
    return about,opts,positions

DOCS={name:compact_docs(name) for name in COMMANDS}

@dataclass
class Node:
    path: tuple
    description: str
    cmd: object = None
    children: list = field(default_factory=list)

    @property
    def options(self):
        return self.cmd.options if self.cmd else []

    @property
    def positions(self):
        return self.cmd.positionals if self.cmd else []

    def doc(self, key, positional=False):
        if not self.cmd:
            return ''
        return DOCS[self.cmd.name][2 if positional else 1].get(key,'')


def make_tree():
    def stripped(c,path):
        n=Node(path,DOCS[c.name][0])
        for ch in c.children:
            if ch!='help':
                original=(c.name+' '+ch).strip()
                n.children.append(stripped(COMMANDS[original],path+(ch,)))
        return n
    def real(c,path):
        n=Node(path,DOCS[c.name][0],c)
        for ch in c.children:
            if ch!='help':
                n.children.append(real(COMMANDS[(c.name+' '+ch).strip()],path+(ch,)))
        if c.children:
            helper=Node(path+('help',),HELP_DESCRIPTION)
            helper.children=[stripped(COMMANDS[(c.name+' '+ch).strip()],helper.path+(ch,)) for ch in c.children if ch!='help']
            helper.children.append(Node(helper.path+('help',),HELP_DESCRIPTION))
            n.children.append(helper)
        return n
    return real(COMMANDS[''],('pueue',))


