"""Dependency-free YAML reader for configuration documents.

It retains source positions and scalar styles so configuration validation can
produce useful diagnostics, rather than silently coercing incompatible types.
"""
from dataclasses import dataclass
from bisect import bisect_right
import re
from diagnostics import debug_quote


class YAMLProblem(Exception):
    pass


@dataclass
class Schema:
    kind: str
    name: str = ''
    fields: dict = None
    item: object = None
    optional: bool = False


@dataclass
class Node:
    kind: str
    value: object
    offset: int
    raw: str = ''


BOOL=Schema('bool')
UINT=Schema('uint')
STRING=Schema('str')
OPT_STRING=Schema('str',optional=True)
PATH=Schema('path',optional=True)
STR_MAP=Schema('map',item=STRING)
SHARED=Schema('struct','Shared',{
    'pueue_directory':PATH, 'runtime_directory':PATH, 'unix_socket_path':PATH,
    'shared_secret_path':PATH, 'pid_path':PATH, 'daemon_cert':PATH,
    'host':OPT_STRING, 'port':OPT_STRING, 'use_unix_socket':BOOL,
})
CLIENT=Schema('struct','Client',{
    'restart_in_place':BOOL, 'dark_mode':BOOL, 'show_expanded_aliases':BOOL,
    'read_local_logs':BOOL, 'max_status_lines':UINT,
    'status_time_format':STRING, 'status_datetime_format':STRING,
})
DAEMON=Schema('struct','Daemon',{
    'pause_group_on_failure':BOOL,'pause_all_on_failure':BOOL,
    'callback':OPT_STRING,'callback_log_lines':UINT,'env_vars':STR_MAP,
})
NESTED=Schema('struct','NestedSettings',{'shared':SHARED,'client':CLIENT,'daemon':DAEMON})
SETTINGS=Schema('struct','Settings',{
    **NESTED.fields,'profiles':Schema('map',item=NESTED),
})


class Reader:
    def __init__(self,text):
        self.text=text.lstrip('\ufeff')
        self.i=0
        self.starts=[0]+[m.end() for m in re.finditer('\n',self.text)]
        self.anchors={}

    def mark(self,offset):
        row=bisect_right(self.starts,offset)-1
        return row+1, offset-self.starts[row]+1

    def location(self,offset):
        line,col=self.mark(offset)
        return '' if (line,col)==(1,1) else f' at line {line} column {col}'

    def syntax(self,problem,offset=None,context='',context_offset=None):
        pos=self.i if offset is None else offset
        text=problem+self.location(pos)
        if context:
            text+=', '+context
            if context_offset is not None:
                text+=self.location(context_offset)
        raise YAMLProblem(text)

    def expected_text(self,spec):
        return {'bool':'a boolean','uint':'usize','str':'a string','path':'path string',
                'map':'a map','struct':'struct '+spec.name}.get(spec.kind,spec.kind)

    def actual_text(self,node):
        if node.kind in ('empty','null'):return 'unit value'
        if node.kind=='map':return 'map'
        if node.kind=='seq':return 'sequence'
        if node.kind=='str':return 'string '+debug_quote(node.value)
        if node.kind=='bool':return 'boolean `'+('true' if node.value else 'false')+'`'
        if node.kind=='int':return 'integer `'+str(node.value)+'`'
        if node.kind=='float':return 'floating point `'+str(node.value)+'`'
        return node.kind

    def validate(self,node,spec,path):
        if not spec:return node
        kind=spec.kind
        if node.kind in ('empty','null') and spec.optional:
            node.value=None
