        if kind in ('struct','map'):
            if kind=='struct' and node.kind=='empty':
                node.kind='map';node.value=[]
                return node
            good=node.kind=='map'
        elif kind=='bool':good=node.kind=='bool'
        elif kind=='uint':good=node.kind=='int' and 0 <= node.value < (1<<64)
        elif kind in ('str','path'):
