"""Configuration discovery, layered profiles, and connection settings."""
import os
import pwd
from datetime import datetime
from diagnostics import Finished, runtime_error, os_error, debug_quote
from yaml_reader import read_settings, YAMLProblem


def home_directory():
    return os.environ.get('HOME') or pwd.getpwuid(os.getuid()).pw_dir


def xdg_directory(variable,fallback):
    path=os.environ.get(variable,'')
    return path if os.path.isabs(path) else fallback


def expand_home(path):
    if path=='~':return home_directory()
    if path.startswith('~/'):return home_directory()+path[1:]
    return path


def merge(a,b):
    out=dict(a)
    for key,val in b.items():
        if isinstance(val,dict) and isinstance(out.get(key),dict):out[key]=merge(out[key],val)
        else:out[key]=val
    return out


class Logger:
    def __init__(self,verbosity):
        self.verbosity=verbosity
        self.messages=[]
        self.color=not os.environ.get('NO_COLOR')
        self.level=2 if verbosity else 0
        env=os.environ.get('RUST_LOG')
        if env:
            ranks={'off':-1,'error':0,'warn':1,'info':2,'debug':3,'trace':4}
            for clause in env.split(','):
                part=clause.split('=')
                if len(part)==1 or part[0] in ('pueue_lib','pueue_lib::settings'):
                    self.level=ranks.get(part[-1],self.level)

    def info(self,message,line):
        if self.level<2:return
        clock=datetime.now().strftime('%H:%M:%S')
        if self.verbosity>=4:
            if self.color:
                self.messages.append(f'  \x1b[2m{clock}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1;32mpueue_lib::settings\x1b[0m\x1b[32m: \x1b[32m{message}\x1b[0m\n'
                                     f'    \x1b[2;3mat\x1b[0m pueue_lib/src/settings.rs:{line} \x1b[2;3mon\x1b[0m main\n\n')
            else:self.messages.append(f'  {clock}  INFO pueue_lib::settings: {message}\n    at pueue_lib/src/settings.rs:{line} on main\n\n')
        elif self.color:
            self.messages.append(f'\x1b[2m{clock}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[2mpueue_lib::settings\x1b[0m\x1b[2m:\x1b[0m {message}\n')
        else:self.messages.append(f'{clock}  INFO pueue_lib::settings: {message}\n')

    def output(self):return ''.join(self.messages)


def read_config(path):
    try:
        with open(path,'rb') as stream:
            content=stream.read()
    except OSError as e:
        if e.errno==21:
            err='Error while reading configuration:\n'+os_error(e)
        else:err=f'I/O error at path {debug_quote(path)} while opening config file:\n'+os_error(e)
        runtime_error(['Failed to read configuration.',err],51)
    try:
        text=content.decode('utf-8')
    except UnicodeDecodeError:
        runtime_error(['Failed to read configuration.','Error while reading configuration:\ninvalid leading UTF-8 octet'],51)
    try:
