def home_directory():
    return os.environ.get('HOME') or pwd.getpwuid(os.getuid()).pw_dir


def xdg_directory(variable,fallback):
    path=os.environ.get(variable,'')
    return path if os.path.isabs(path) else fallback


def expand_home(path):
    if path=='~':return home_directory()
    if path.startswith('~/'):return home_directory()+path[1:]
    return path


def merge(a,b):
    out=dict(a)
    for key,val in b.items():
        if isinstance(val,dict) and isinstance(out.get(key),dict):out[key]=merge(out[key],val)
        else:out[key]=val
    return out


class Logger:
    def __init__(self,verbosity):
        self.verbosity=verbosity
        self.messages=[]
        self.color=not os.environ.get('NO_COLOR')
        self.level=2 if verbosity else 0
        env=os.environ.get('RUST_LOG')
        if env:
            ranks={'off':-1,'error':0,'warn':1,'info':2,'debug':3,'trace':4}
            for clause in env.split(','):
                part=clause.split('=')
                if len(part)==1 or part[0] in ('pueue_lib','pueue_lib::settings'):
                    self.level=ranks.get(part[-1],self.level)

    def info(self,message,line):
        if self.level<2:return
        clock=datetime.now().strftime('%H:%M:%S')
        if self.verbosity>=4:
