                self.messages.append(f'  \x1b[2m{clock}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1;32mpueue_lib::settings\x1b[0m\x1b[32m: \x1b[32m{message}\x1b[0m\n'
