"""Decoder for self-describing, length-delimited CBOR protocol values."""
import struct
from diagnostics import debug_quote

class DecodeError(Exception):pass


def decode(data):
    offset=0
    def take(n):
        nonlocal offset
        if offset+n>len(data):raise DecodeError('short input')
        result=data[offset:offset+n];offset+=n
        return result
    def one():
        c=take(1)[0];major=c>>5;additional=c&31
        if major==7:
            if additional==20:return False
            if additional==21:return True
            if additional in (22,23):return None
            if additional==25:return struct.unpack('>e',take(2))[0]
            if additional==26:return struct.unpack('>f',take(4))[0]
            if additional==27:return struct.unpack('>d',take(8))[0]
            raise DecodeError('unsupported simple value')
        if additional<24:n=additional
        elif additional in (24,25,26,27):n=int.from_bytes(take(1<<(additional-24)),'big')
        else:raise DecodeError('indefinite value')
        if major==0:return n
        if major==1:return -1-n
        if major==2:return take(n)
        if major==3:
            try:return take(n).decode('utf8')
            except UnicodeDecodeError:raise DecodeError('invalid text')
        if major==4:return [one() for _ in range(n)]
        if major==5:
            d={}
            for _ in range(n):
                key=one();value=one()
                try:d[key]=value
                except TypeError:raise DecodeError('invalid map key')
            return d
        if major==6:return one()
        raise DecodeError('unknown type')
    result=one()
    if offset!=len(data):raise DecodeError('trailing input')
    return result


def pretty(v):
    if v is None:return 'Null'
    if isinstance(v,bool):return 'Bool(\n    '+str(v).lower()+',\n)'
    if isinstance(v,int):return 'Integer(\n    '+str(v)+',\n)'
    if isinstance(v,float):return 'Float(\n    '+str(v)+',\n)'
    if isinstance(v,str):return 'Text(\n    '+debug_quote(v)+',\n)'
    if isinstance(v,bytes):return 'Bytes(\n    [\n'+''.join('        '+str(c)+',\n' for c in v)+'    ],\n)'
    if isinstance(v,list):return 'Array(\n    [\n'+''.join('        '+pretty(x).replace('\n','\n        ')+',\n' for x in v)+'    ],\n)'
    if isinstance(v,dict):
        text='Map(\n    {\n'
        for key,val in v.items():
            text+='        '+pretty(key).replace('\n','\n        ')+': '+pretty(val).replace('\n','\n        ')+',\n'
        return text+'    },\n)'
    raise DecodeError('unknown value')
