"""Executable entry point."""
import os
import sys
from cli import Parser
from diagnostics import Finished
from runtime import run


def main():
    program=os.path.basename(sys.argv[0]) or 'pueue'
    try:
        parsed=Parser(program).parse(sys.argv[1:])
        run(parsed)
    except Finished as result:
        if result.out:sys.stdout.write(result.out)
        if result.err:sys.stderr.write(result.err)
