    return take(size,'request body')


def connect(settings,secret,logger):
    if settings['use_unix_socket']:
        stream=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM)
        path=settings['socket']
        try:
            stream.connect(path)
        except (OSError,ValueError) as e:
            if len(os.fsencode(path))>=108:
                detail='path must be shorter than SUN_LEN'
            elif isinstance(e,OSError) and e.errno is not None:detail=os_error(e)
            else:detail=str(e)
            stream.close()
            runtime_error(['Failed to initialize client.','Failed to initialize stream.',
                           f'I/O error at path {debug_quote(path)} while connecting to daemon. Did you start it?:\n'+detail],85,CLIENT_SOURCE)
    else:
        try:
            stream=socket.create_connection((settings['host'],int(settings['port'])))
            context=ssl.create_default_context(cafile=settings['certificate'])
            stream=context.wrap_socket(stream,server_hostname=settings['host'])
        except (OSError,ValueError) as e:
            detail=os_error(e) if isinstance(e,OSError) and e.errno is not None else str(e)
            runtime_error(['Failed to initialize client.','Failed to initialize stream.',detail],85,CLIENT_SOURCE)
    try:
        send_packet(stream,secret)
        version=receive_packet(stream)
    except PacketProblem as e:
        stream.close()
        runtime_error(['Failed to initialize client.','Failed to receive version during handshake with daemon.',str(e)],97,CLIENT_SOURCE)
    if not version:
        stream.close()
        runtime_error(['Failed to initialize client.','Daemon went away after sending secret. Did you use the correct secret?'],99,CLIENT_SOURCE)
    version=version.decode('utf-8',errors='replace')
    logger.warning("Different protocol version detected '"+version+"'. Consider updating and restarting the daemon.")
    return stream


def run(parsed):
    if parsed.command.name=='completions':
        complete_command(parsed)
    options=parsed.root.values
    logger=Logger(options.get('verbose',0))
    try:
        config=load_config(options,logger)
        settings=connection_settings(config)
        if not settings['use_unix_socket']:
            certificate(settings)
        secret=read_secret(settings['secret'])
        stream=connect(settings,secret,logger)
        try:
            # Every interactive operation starts with the current daemon state.
            send_packet(stream,b'\x66Status')
            response=receive_packet(stream)
        except PacketProblem as e:
            runtime_error(str(e),106,COMMAND_SOURCE)
        finally:stream.close()
        from wire_value import decode, pretty, DecodeError
        try:
            value=decode(response)
        except DecodeError:
            runtime_error('Failed to deserialize response.',106,COMMAND_SOURCE)
        if isinstance(value,dict) and any(k in value for k in ('Success','Failure')):
            err=('\x1b[31mThe application panicked (crashed).\x1b[0m\n'
                 'Message:  \x1b[36minternal error: entered unreachable code\x1b[0m\n'
                 'Location: \x1b[35m'+COMMAND_SOURCE+'\x1b[0m:\x1b[35m110\x1b[0m\n\n'
                 'Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.\n'
                 'Run with RUST_BACKTRACE=full to include source snippets.\n')
            finish(err=err,status=101)
        runtime_error('Got unexpected but valid message. Are you up-to-date?:\n'+pretty(value),106,COMMAND_SOURCE)
    except Finished as e:
        e.err=logger.output()+e.err
        raise
